export type Priority = 'low' | 'medium' | 'high';
export type Status = string;

/**
 * Provenance of stored content (TR-16).
 *   system   — generated by the server itself (catalog, built-in prompts).
 *   user     — authored by the local user/agent (default).
 *   external — ingested from outside (web, connectors, third-party files);
 *              content the user did not produce and cannot vouch for.
 */
export type TrustLevel = 'system' | 'user' | 'external';

/**
 * Claim/lease metadata for a task (U-01).
 *
 * This is coordination state, NOT content: `tasks_renew` updates
 * `heartbeatAt`/`expiresAt` only and deliberately leaves the task's
 * `updatedAt` (and the future MU-02 `version`) untouched. A heartbeat must
 * never invalidate another client's optimistic-lock token, otherwise every
 * renew would manufacture a false CONFLICT.
 */
export interface TaskClaim {
  /** MCP session id of the holder (transport session / per-connection id). */
  bySessionId: string;
  /** Authenticated user id, when the session carries one. */
  byUserId?: string;
  /** Free-form client label supplied by the caller (e.g. "claude-code", "opencode"). */
  client?: string;
  claimedAt: string; // ISO — first claim, preserved across renewals
  heartbeatAt: string; // ISO — last claim/renew
  expiresAt: string; // ISO — lease deadline; expired claims do not block
}

export interface Task {
  id: string;
  project: string; // namespace/key for project
  title: string;
  description?: string;
  status: Status;
  /** V-03: project-defined task type; legacy tasks without it are 'task'. */
  type?: string;
  priority: Priority;
  tags?: string[];
  createdAt: string; // ISO
  updatedAt: string; // ISO
  links?: string[]; // file paths or URLs
  // Optional parent task ID to support hierarchical task trees
  parentId?: string;
  // Dependency graph: task IDs this task depends on (all must be completed before this can start)
  dependsOn?: string[];
  /** U-01: active lease holder; absent/expired = free to claim. */
  claim?: TaskClaim;
  // Soft-delete lifecycle
  archived?: boolean;
  trashed?: boolean;
  archivedAt?: string; // ISO
  trashedAt?: string; // ISO
}

export interface KnowledgeDocMeta {
  id: string;
  project: string;
  title: string;
  tags?: string[];
  createdAt: string;
  updatedAt: string;
  source?: string; // optional source path/url
  // Provenance (TR-16); absent in legacy docs = treated as 'user'
  trustLevel?: TrustLevel;
  // Optional hierarchical fields for knowledge tree
  parentId?: string; // parent knowledge doc id
  type?: string; // e.g. component, api, schemas, routes, overview
  // Soft-delete lifecycle
  archived?: boolean;
  trashed?: boolean;
  archivedAt?: string; // ISO
  trashedAt?: string; // ISO
  // Versioning (TD-005)
  version?: number; // current version number (1-based)
  history?: Array<{ version: number; updatedAt: string; title?: string }>; // prior versions
}

export interface KnowledgeDoc extends KnowledgeDocMeta {
  content: string; // markdown
}

export interface SearchResult<T> {
  id: string;
  score: number;
  item: T;
  path?: string;
  /** Raw BM25 score when the item came from the lexical channel. */
  bm25Score?: number;
  /** BM25 score as a share of the query's maximum achievable score (0..1). */
  bm25Confidence?: number;
  /** Number of verbatim anchors (paths, symbols, ticket ids) found in the text. */
  exactMatches?: number;
  /** Raw cosine similarity when the item came from the vector channel. */
  vectorScore?: number;
}

// Recursive node type for representing task trees
export interface TaskTreeNode extends Task {
  children: TaskTreeNode[];
}
